import * as ftyp from './boxes/ftyp.mjs'
import * as mvhd from './boxes/mvhd.mjs'
import * as hdlr from './boxes/hdlr.mjs'
import * as data from './boxes/data.mjs'

import BufferView from '../viewer.mjs'
import { mergeObjects } from '../utils/objects.mjs'
import { encodeString } from '../utils/strings.mjs'

const metaElements = {
  '©nam': 'title',
  '©day': 'date',
  '©cpy': 'copyright',
  '©ART': 'artist',
  aART: 'album_artist',
  '©wrt': 'composer',
  desc: 'description',
  '©cmt': 'comment',
  ldes: 'synopsis',
  '©gen': 'genre',
  '©grp': 'grouping',
  tvsh: 'show',
  tven: 'episode_id',
  tves: 'episode_sort',
  tvsn: 'season_number',
  '©lyr': 'lyrics',
  cpil: 'compilation',
  tvnn: 'network',
  stik: 'media_type',
  hdvd: 'hd_video',
  pgap: 'gapless_playback',
  '©too': 'encoding_tool'
}

const containerBoxes = ['meta', 'moov', 'udta', 'ilst']

export function decodeMetadata (buffer) {
  const view = new BufferView(buffer)
  const boxes = []
  let metadata = {}
  let offset = 0

  while (offset < view.byteLength) {
    const size = view.getUint32(offset)
    const type = view.getString(offset + 4, 4)
    let body = null

    if (size === 1) {
      const largeSize = view.getUint64(offset + 8)
      body = view.getUint8(offset + 16, largeSize, true)
      offset += largeSize
    } else if (size === 0) {
      body = view.getUint8(offset + 8, view.byteLength - offset - 8, true)
      offset = view.byteLength
    } else {
      body = view.getUint8(offset + 8, size - 8, true)
      offset += size
    }

    let parsed = null
    if (type === 'ftyp') parsed = ftyp.parse(body)
    if (type === 'mvhd') parsed = mvhd.parse(body)
    if (type === 'data') parsed = data.parse(body)
    if (type === 'hdlr') parsed = hdlr.parse(body)

    if (containerBoxes.includes(type)) {
      const decoded = decodeMetadata(type === 'meta' ? body.slice(4) : body)
      parsed = decoded.boxes
      metadata = mergeObjects(metadata, decoded.metadata)
    }

    if (typeof metaElements[type] !== 'undefined') {
      const key = metaElements[type]
      const decoded = decodeMetadata(body)
      parsed = decoded.boxes
      metadata[key] = decoded.boxes[0].value
    }

    boxes.push({
      type,
      raw: parsed === null ? body : null,
      value: parsed
    })
  }

  return { boxes, metadata }
}

export function validate (metadata, boxes, strict) {
  for (const key in metadata) {
    if (typeof metadata[key] !== 'string') {
      throw new Error('Metadata value should be a string')
    }
  }

  const validateBox = (box) => {
    const { type, raw, value } = box

    if (value === null && raw === null) {
      throw new Error(`Invalid value "${type}"`)
    }

    if (typeof type !== 'string' || type.length !== 4) {
      throw new Error(`Invalid header type "${type}"`)
    }

    if (
      raw !== null &&
      (!Array.isArray(raw) || raw.some(byte => byte > 255 || byte < 0))
    ) {
      throw new Error(`Invalid byte in box raw ${type}`)
    }

    if (type === 'ftyp') ftyp.validate(value)
    if (type === 'mvhd') mvhd.validate(value)
    if (type === 'data') data.validate(value)
    if (type === 'hdlr') hdlr.validate(value)

    if (
      containerBoxes.includes(type) ||
      typeof metaElements[type] !== 'undefined'
    ) {
      value.forEach(validateBox)
    }
  }

  boxes.forEach(validateBox)
}

export function encodeMetadata (metadata, boxes, options) {
  boxes = removeMetadata(boxes)
  boxes = addMetadata(metadata, boxes)
  return encodeBox(boxes, options)
}

function removeMetadata (boxes) {
  const result = []
  for (let i = 0; i < boxes.length; i++) {
    const box = boxes[i]
    if (typeof metaElements[box.type] !== 'undefined') {
      continue
    }

    if (containerBoxes.includes(box.type)) {
      box.value = removeMetadata(box.value)
    }

    result.push(box)
  }

  return result
}

function addMetadata (metadata, boxes) {
  let moovIdx = boxes.map(box => box.type).indexOf('moov')
  if (moovIdx < 0) {
    boxes.push({
      type: 'moov',
      raw: null,
      value: []
    })
    moovIdx = boxes.length - 1
  }

  let udtaIdx = boxes[moovIdx].value.map(box => box.type).indexOf('udta')
  if (udtaIdx < 0) {
    boxes[moovIdx].value.push({
      type: 'udta',
      raw: null,
      value: []
    })
    udtaIdx = boxes[moovIdx].value.length - 1
  }

  let metaIdx = boxes[moovIdx].value[udtaIdx].value.map(box => box.type).indexOf('meta')
  if (metaIdx < 0) {
    boxes[moovIdx].value[udtaIdx].value.push({
      type: 'meta',
      raw: null,
      value: []
    })
    metaIdx = boxes[moovIdx].value[udtaIdx].value.length - 1
  }

  const hdlrIdx = boxes[moovIdx].value[udtaIdx].value[metaIdx].value.map(box => box.type).indexOf('hdlr')
  if (hdlrIdx < 0) {
    boxes[moovIdx].value[udtaIdx].value[metaIdx].value.unshift({
      type: 'hdlr',
      raw: null,
      value: {
        handlerType: [109, 100, 105, 114],
        name: ''
      }
    })
  }

  let ilstIdx = boxes[moovIdx].value[udtaIdx].value[metaIdx].value.map(box => box.type).indexOf('ilst')
  if (ilstIdx < 0) {
    boxes[moovIdx].value[udtaIdx].value[metaIdx].value.push({
      type: 'ilst',
      raw: null,
      value: []
    })
    ilstIdx = boxes[moovIdx].value[udtaIdx].value[metaIdx].value.length - 1
  }

  for (const key in metadata) {
    if (!Object.hasOwn(metadata, key)) continue

    for (const metaType in metaElements) {
      if (!Object.hasOwn(metaElements, metaType)) continue
      if (key !== metaElements[metaType]) continue

      boxes[moovIdx].value[udtaIdx].value[metaIdx].value[ilstIdx].value.push({
        type: metaType,
        raw: null,
        value: [
          {
            type: 'data',
            raw: null,
            value: metadata[key]
          }
        ]
      })
    }
  }

  return boxes
}

function encodeBox (boxes, options) {
  const bytes = []
  for (let i = 0; i < boxes.length; i++) {
    const box = boxes[i]
    const { type, raw, value } = box
    const sizeView = new BufferView(4)

    let encoded = null
    if (value === null) encoded = raw
    if (type === 'ftyp') encoded = ftyp.encode(value)
    if (type === 'mvhd') encoded = mvhd.encode(value)
    if (type === 'data') encoded = data.encode(value)
    if (type === 'hdlr') encoded = hdlr.encode(value)

    if (
      containerBoxes.includes(type) ||
      typeof metaElements[type] !== 'undefined'
    ) {
      if (value.length === 0) continue
      encoded = type === 'meta' ? [0, 0, 0, 0] : []
      encodeBox(value, options).forEach(byte => encoded.push(byte))
    }

    if (encoded === null) throw new Error(`Unable to encode "${type}"`)

    sizeView.setUint32(0, encoded.length + 8)
    const typeBytes = encodeString(type)
    bytes.push(...sizeView.getUint8(0, 4), ...typeBytes)
    encoded.forEach(byte => bytes.push(byte))
  }

  return new Uint8Array(bytes)
}
